SELECT department_id, COUNT(*) AS employee_count, AVG(salary) AS avg_salary
FROM Employees
GROUP BY department_id;

base_template_py:
import pandas as pd

def group_aggregate(employees: pd.DataFrame) -> pd.DataFrame:
    return employees.groupby("department_id").agg(
        employee_count=("id", "count"),
        avg_salary=("salary", "mean")
    ).reset_index()

import pandas as pd

def window_ranking(scores: pd.DataFrame) -> pd.DataFrame:
    scores["rank"] = scores["score"].rank(method="dense", ascending=False)
    return scores.sort_values(by="score", ascending=False).reset_index(drop=True)

import pandas as pd

def window_offset(logs: pd.DataFrame) -> pd.DataFrame:
    logs = logs.sort_values("id").reset_index(drop=True)
    is_consec = (logs["num"] == logs["num"].shift(1)) & (logs["num"] == logs["num"].shift(-1))
    return logs[is_consec][["num"]].drop_duplicates().rename(columns={"num": "ConsecutiveNums"})

