SELECT visited_on,
       SUM(amount) OVER (
           ORDER BY visited_on
           ROWS BETWEEN 6 PRECEDING AND CURRENT ROW
       ) AS amount,
       ROUND(AVG(amount) OVER (
           ORDER BY visited_on
           ROWS BETWEEN 6 PRECEDING AND CURRENT ROW
       ), 2) AS average_amount
FROM Customer;

base_template_py:
import pandas as pd

def running_total(customer: pd.DataFrame) -> pd.DataFrame:
    daily = customer.groupby("visited_on")["amount"].sum().reset_index()
    daily["rolling_amount"] = daily["amount"].rolling(window=7, min_periods=7).sum()
    daily["average_amount"] = (daily["rolling_amount"] / 7).round(2)
    return daily.dropna().reset_index(drop=True)

import pandas as pd

def top_n_per_group(employee: pd.DataFrame, department: pd.DataFrame) -> pd.DataFrame:
    employee["rnk"] = employee.groupby("departmentId")["salary"].rank(method="dense", ascending=False)
    top3 = employee[employee["rnk"] <= 3]
    merged = top3.merge(department, left_on="departmentId", right_on="id", suffixes=("_emp", "_dept"))
    return merged[["name_dept", "name_emp", "salary"]].rename(columns={"name_dept": "Department", "name_emp": "Employee", "salary": "Salary"})

import pandas as pd

def self_join(employee: pd.DataFrame) -> pd.DataFrame:
    merged = employee.merge(employee, left_on="managerId", right_on="id", suffixes=("", "_mgr"))
    return merged[merged["salary"] > merged["salary_mgr"]][["name"]].rename(columns={"name": "Employee"})

import pandas as pd

def gaps_and_islands(df: pd.DataFrame) -> pd.DataFrame:
    df["log_date"] = pd.to_datetime(df["log_date"])
    df = df.sort_values("log_date").reset_index(drop=True)
    df["island"] = df["log_date"] - pd.to_timedelta(df.index, unit="D")
    return df.groupby("island").agg(start_date=("log_date", "min"), end_date=("log_date", "max"), streak_length=("log_date", "count")).reset_index(drop=True)

